// The 40 September 2026 enquiries (knowledge/Aangan_Sep 2026_Enquiries.pdf),
// reduced to the facts the agent would collect, with the outcome Nikhil's
// rubric (qualified.md) gives. This is the labelled set the policy is tested
// against, and the Step 6 replay script will reuse it.
//
// `expected` is what the rubric says, not always what the front desk did.

import type { LeadFacts } from "../../lib/policy";
import type { LeadScore } from "../../lib/types";

export interface EnquiryCase {
  id: string;
  channel: "phone" | "whatsapp" | "form";
  at: string; // ISO, IST
  note: string;
  /** Non-new-project calls have no facts to score. */
  facts: LeadFacts | null;
  expected: LeadScore | "missed_call" | "existing_client_escalate";
}

const base: LeadFacts = {
  intent: "design_and_execution",
  project_kind: "home",
  scope_kind: "full_home",
  room_count: null,
  bhk: null,
  area: null,
  size_sqft: null,
  budget_max_inr: null,
  deadline_date: null,
  site_available_in_weeks: null,
  decision_maker: "unknown",
};
const f = (o: Partial<LeadFacts>): LeadFacts => ({ ...base, ...o });

